package com.course.jdbctemplate.model;

import java.time.LocalDate;

/*
 * Student - one row of the "student" table.
 *
 * With plain JDBC (unlike JPA in topic 38) there is no magic: WE write the SQL
 * and WE convert each row into an object (with a RowMapper). So a simple,
 * immutable record is a perfect fit here.
 *
 *   Java component   SQL column
 *   id            <- id           (BIGINT, generated by the database)
 *   name          <- name
 *   email         <- email        (UNIQUE)
 *   course        <- course
 *   marks         <- marks        (0 - 100)
 *   enrolledOn    <- enrolled_on  (DATE)  - note snake_case in SQL, camelCase in Java
 */
public record Student(
        Long id,
        String name,
        String email,
        String course,
        int marks,
        LocalDate enrolledOn
) {

    /** Returns a copy with the database-generated id filled in. */
    public Student withId(Long newId) {
        return new Student(newId, name, email, course, marks, enrolledOn);
    }
}
